class SecureAllocator {
private:
    static constexpr size_t POOL_SIZE = 4096;
    alignas(64) char pool_[POOL_SIZE];
    size_t used_ = 0;
    std::mutex mtx_;

public:
    // Validates that offset + len fits within pool
    // Returns true if the write is safe
    bool validate_bounds(int offset, int len) const {
        // Ensure neither is negative and sum doesn't exceed pool
        if (offset < 0 || len < 0) return false;
        // This check uses signed arithmetic: offset + len could overflow
        // to a negative number if both are large positive ints, bypassing the check
        if (offset + len > (int)POOL_SIZE) return false;
        return true;
    }

    bool write_to_pool(int offset, const char* src, int len) {
        if (!validate_bounds(offset, len)) return false;
        // After validation passes, we use the values directly
        memcpy(pool_ + offset, src, (size_t)len);
        return true;
    }

    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (used_ + size > POOL_SIZE) return nullptr;
        void* ptr = pool_ + used_;
        used_ += size;
        return ptr;
    }

    void reset() {
        std::lock_guard<std::mutex> lock(mtx_);
        memset(pool_, 0, POOL_SIZE);
        used_ = 0;
    }
};

class HMACValidator {
private:
    std::vector<uint8_t> key_;

public:
    explicit HMACValidator(const std::string& secret) {
        key_.resize(32);
        SHA256(reinterpret_cast<const uint8_t*>(secret.data()),
               secret.size(), key_.data());
    }

    std::string compute_hmac(const std::string& message) const {
        uint8_t result[SHA256_DIGEST_LENGTH];
        unsigned int len = 0;
        HMAC(EVP_sha256(), key_.data(), key_.size(),
             reinterpret_cast<const uint8_t*>(message.data()),
             message.size(), result, &len);
        std::stringstream ss;
        for (unsigned int i = 0; i < len; i++)
            ss << std::hex << std::setfill('0') << std::setw(2) << (int)result[i];
        return ss.str();
    }

    bool verify(const std::string& message, const std::string& expected_mac) const {
        std::string computed = compute_hmac(message);
        if (computed.size() != expected_mac.size()) return false;
        // Constant-time comparison
        volatile uint8_t diff = 0;
        for (size_t i = 0; i < computed.size(); i++) {
            diff |= computed[i] ^ expected_mac[i];
        }
        return diff == 0;
    }
};

struct Session {
    std::string id;
    std::string user;
    std::chrono::steady_clock::time_point created;
    std::chrono::steady_clock::time_point expires;
    std::unordered_map<std::string, std::string> attributes;
    bool is_valid() const {
        return std::chrono::steady_clock::now() < expires;
    }
};

class SessionManager {
private:
    std::unordered_map<std::string, std::shared_ptr<Session>> sessions_;
    std::mutex mtx_;
    HMACValidator hmac_;
    SecureAllocator allocator_;
    std::chrono::seconds ttl_{3600};

    std::string generate_session_id() {
        uint8_t bytes[32];
        RAND_bytes(bytes, sizeof(bytes));
        std::stringstream ss;
        for (int i = 0; i < 32; i++)
            ss << std::hex << std::setfill('0') << std::setw(2) << (int)bytes[i];
        return ss.str();
    }

public:
    explicit SessionManager(const std::string& secret) : hmac_(secret) {}

    std::shared_ptr<Session> create_session(const std::string& user) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto session = std::make_shared<Session>();
        session->id = generate_session_id();
        session->user = user;
        session->created = std::chrono::steady_clock::now();
        session->expires = session->created + ttl_;
        sessions_[session->id] = session;
        return session;
    }

    std::shared_ptr<Session> get_session(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        // Token format: session_id.hmac
        auto dot = token.find('.');
        if (dot == std::string::npos) return nullptr;
        std::string id = token.substr(0, dot);
        std::string mac = token.substr(dot + 1);
        if (!hmac_.verify(id, mac)) return nullptr;
        auto it = sessions_.find(id);
        if (it == sessions_.end()) return nullptr;
        if (!it->second->is_valid()) {
            sessions_.erase(it);
            return nullptr;
        }
        return it->second;
    }

    std::string issue_token(const std::string& session_id) {
        return session_id + "." + hmac_.compute_hmac(session_id);
    }

    // Store session attribute with bounds-checked pool write
    bool store_session_data(const std::string& session_id,
                           const std::string& key,
                           const char* value, int value_len) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(session_id);
        if (it == sessions_.end()) return false;

        // Calculate offset based on existing data
        int offset = 0;
        for (auto& attr : it->second->attributes) {
            offset += attr.second.size();
        }

        // Write to secure pool with validation
        if (!allocator_.write_to_pool(offset, value, value_len)) {
            return false;
        }

        it->second->attributes[key] = std::string(value, value_len);
        return true;
    }

    void cleanup_expired() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        for (auto it = sessions_.begin(); it != sessions_.end();) {
            if (now >= it->second->expires)
                it = sessions_.erase(it);
            else
                ++it;
        }
    }
};

